// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address newLog, address caller) public {
        vm.assume(newLog != address(0));
        vm.assume(caller != address(0));

        bool okBefore;
        try c.SetLogFile(newLog) {
            okBefore = true;
        } catch {
            okBefore = false;
        }

        c.Initialized();

        bool okAfter;
        try c.SetLogFile(newLog) {
            okAfter = true;
        } catch {
            okAfter = false;
        }

        assertTrue(okAfter == false);
    }
}
